 "content": "def transform(grid):
    # Separator-colored full rows/columns divide repeated panels. A panel is marked
    # when its unusual-color cells form an orthogonally adjacent pair.
    h, w = len(grid), len(grid[0])
    sep = grid[0][2] if w == 5 else None
    row_seps = [r for r in range(h) if all(v == grid[r][0] for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    def bands(n, seps):
        out=[]; start=0
        for p in seps:
            if p >= start:
                if p > start: out.append((start,p))
                start=p+1
        if start<n: out.append((start,n))
        return out
    rb=bands(h,row_seps); cb=bands(w,col_seps)
    result=[]
    for r0,r1 in rb:
        line=[]
        for c0,c1 in cb:
            cells=[(r,c) for r in range(r0,r1) for c in range(c0,c1)
                   if grid[r][c] not in (grid[r0][c0],)]
            found=False
            for r,c in cells:
                if (r+1,c) in cells or (r,c+1) in cells:
                    found=True; break
            line.append(1 if found else grid[r0][c0])
        result.append(line)
    return result
